/* THE TARGETS, WORKED OUT IN CODE (Asaf, 1 Nov 2026).
 * He was handed 2,705 kcal: his maintenance, with no deficit for his goal and
 * his workouts counted twice - once every day inside the activity factor
 * (1.2-1.9, the standard five, which are DEFINED by training frequency) and
 * again on the day itself by actBonus/tgtOn. This replaces the calculation,
 * the nutrition setup's questions, the result screen, the profile's targets
 * card, and adds the one-time update for existing users and the trend-based
 * adjustment offer. Generated by a scratch script from the blocks it replaces.
 *
 *   node tools/patch-targets.mjs [--undo]
 */
import fs from 'fs';
